--该控件实现：Grid下面多页，每个页（子Grid）下面多个元素。滑动结果用页对齐。
PageAndItem = class("PageAndItem")
local this = PageAndItem;
this.pageIndex = 1;--用于点亮下面的点
this.pageCount = 1;
this.dotBGs = {}
this.sheetOriginPos = nil;
this.dotOffset =
{
    0,
    -25,
    -50,
    -75,
    -100,
}

function PageAndItem:ctor()

end

function PageAndItem:InitPanel(mGameObject)
    self.transform = mGameObject.transform;
    self:FindComponent()
    ---加载后需要做什么写在这里

    self:Init();
end

function PageAndItem:FindComponent()
    self.scrollView = self.transform:Find("ScrollView"):GetComponent("UIScrollView");
    self.pageGrid = self.transform:Find("ScrollView/PageGrid"):GetComponent("UIGrid");
    self.centerOnChild = self.transform:Find("ScrollView/PageGrid"):GetComponent("UICenterOnChild");
    self.pageRecycle = self.transform:Find("PageRecycle");
    self.pagePrefab = self.transform:Find("PageRecycle/ItemPage").gameObject;
    self.itemRecycle = self.transform:Find("ItemRecycle");
    self.itemPrefab = self.transform:Find("ItemRecycle/GoodsItem").gameObject;

    self.sheet = self.transform:Find("Sheet").transform;
    self.dot = self.transform:Find("Sheet/Dot").gameObject;
    self.dotBG1 = self.transform:Find("Sheet/DotBG1").gameObject;
    self.dotBG2 = self.transform:Find("Sheet/DotBG2").gameObject;
    self.dotBG3 = self.transform:Find("Sheet/DotBG3").gameObject;
    self.dotBG4 = self.transform:Find("Sheet/DotBG4").gameObject;
    self.dotBG5 = self.transform:Find("Sheet/DotBG5").gameObject;
    table.insert(this.dotBGs, self.dotBG1);
    table.insert(this.dotBGs, self.dotBG2);
    table.insert(this.dotBGs, self.dotBG3);
    table.insert(this.dotBGs, self.dotBG4);
    table.insert(this.dotBGs, self.dotBG5);
    if (this.sheetOriginPos == nil) then
        this.sheetOriginPos = self.sheet.localPosition;
    end
end

function PageAndItem:Init()
    self.pageUsedItemList = {};
    self.pageRecycledItemList = {};

    self.itemUsedItemList = {};
    self.itemRecycledItemList = {};
    if (self.scrollView.onDragFinished) then
        self.scrollView.onDragFinished = self.scrollView.onDragFinished + function () self:OnDragFinished(); end
    else
        self.scrollView.onDragFinished = function () self:OnDragFinished(); end
    end
end

function PageAndItem:OnDragFinished()
    if (self.pageUsedItemList ~= nil) then
        coroutine.start(function()
            coroutine.wait(0.5)
            for i = 1, #self.pageUsedItemList do
                if (self.centerOnChild.centeredObject == self.pageUsedItemList[i].gameObject) then
                    this.pageIndex = i;
                    break;
                end
            end
            self:SetDot();
        end);
    end
end

function PageAndItem:Construct(datas, itemCountPerPage, itemLua, tab)
    local totalGoodsCount = #datas;

    local lastPageItemCount = totalGoodsCount % itemCountPerPage;
    this.pageCount = math.ceil(totalGoodsCount / itemCountPerPage);
    local dataIndex = 1;
    PrefabTool.AdjustPrefabItemCount(this.pageCount, self.pageRecycle, self.pageGrid.transform,
            self.pageUsedItemList, self.pageRecycledItemList, self.pagePrefab, nil);

    PrefabTool.AdjustPrefabItemCount(totalGoodsCount, self.itemRecycle, self.pageGrid.transform,
            self.itemUsedItemList, self.itemRecycledItemList, self.itemPrefab, itemLua);

    if (totalGoodsCount > 0) then
        for i = 1, this.pageCount do
            local itemGrid = self.pageUsedItemList[i];
            itemGrid.name = "itemPage" .. i;
            local count = itemCountPerPage;
            if (lastPageItemCount ~= 0 and i == this.pageCount) then
                count = lastPageItemCount;
            end

            for j = dataIndex, dataIndex + count - 1 do
                self.itemUsedItemList[j].transform.parent = itemGrid.transform;
                self.itemUsedItemList[j]:SetItem(datas[dataIndex], tab, dataIndex);
                dataIndex = dataIndex + 1;
            end
            itemGrid:GetComponent("UIGrid"):Reposition();
        end
        self.pageGrid:Reposition();
        self.scrollView:ResetPosition();
        self.centerOnChild:CenterOn(self.pageUsedItemList[1].transform);

        this.pageIndex = 1;
        if (this.pageCount > 1) then
            local offset = this.dotOffset[this.pageCount];
            self.sheet.localPosition = Vector3.New(this.sheetOriginPos.x + offset, this.sheetOriginPos.y, this.sheetOriginPos.z);
            for i = 1, 5 do
                if (i <= this.pageCount) then
                    this.dotBGs[i]:SetActive(true);
                else
                    this.dotBGs[i]:SetActive(false);
                end
            end
            self.dot:SetActive(true);
            self:SetDot();
        else
            self.dot:SetActive(false);
            for i = 1, 5 do
                this.dotBGs[i]:SetActive(false);
            end
        end
    else
        self.dot:SetActive(false);
        for i = 1, 5 do
            this.dotBGs[i]:SetActive(false);
        end
    end
end

function PageAndItem:SetDot()
    self.dot.transform.localPosition = this.dotBGs[this.pageIndex].transform.localPosition;
end

function PageAndItem:Update()
    if (self.itemUsedItemList ~= nil) then
        for i = 1, #self.itemUsedItemList do
            self.itemUsedItemList[i]:UpdateTime();
        end
    end
end